/bin/bash -lc "python3 - <<'PY'
import subprocess,json
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001']))
print('TOP KEYS',list(r))
for k,v in r.items():
 if k"'!='"'context': print(k,json.dumps(v,indent=2))
c=r.get('context',{})
print('CONTEXT KEYS',list(c))
for k,v in c.items():
 if k not in ('history','retrieval','knowledge'): print(k,json.dumps(v,indent=2)[:18000])
print('HISTORY SUMMARY')
for h in c.get('history',[]):
 print(json.dumps({k:h.get(k) for k in ['id','status','config','wall_seconds','note','error']}),h.get('validation',{}).get('auc'),h.get('validation',{}).get('logloss'))
PY"

